var K = 8.9875517923e9; // Coulomb constant, N·m²·C⁻²
function force(q1, q2, r){ if(!(r>0)) return NaN; return K*q1*q2/(r*r); } // N (signed)
var EXPORTS = { force:force, K:K };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CoulombForgePure = EXPORTS; }
